const onlinePanel=document.createElement('div');onlinePanel.append(item('Online drift battles','Join a room, select the same map and difficulty, and compare live scores. Career rewards use local NPC results.'));let mp=window.WilcoMP?.mount('drift',{container:onlinePanel,snapshot:()=>({active:active||finished,map:session?.map??mapId,diff:session?.diff??difficulty,score:Math.floor(score),combo:Math.floor(peak),x:p?.x||0,z:p?.z||0,yaw:p?.yaw||0,car:selectedSpec?.id??save.selected,done:finished,online:!!session?.online,combat:!!session?.combat,damage,shot:shotEvent}),validate:s=>{if(!s||![s.map,s.diff,s.score,s.combo,s.x,s.z,s.yaw,s.car].every(Number.isFinite)||Math.abs(s.x)>500||Math.abs(s.z)>500||!Number.isInteger(s.car)||!cars[s.car]||!Number.isInteger(s.map)||!maps[s.map])return null;return {active:!!s.active,map:s.map,diff:clamp(Math.floor(s.diff),0,3),score:clamp(s.score,0,1e7),combo:clamp(s.combo,0,1e7),x:s.x,z:s.z,yaw:s.yaw,car:s.car,done:!!s.done,online:!!s.online,combat:!!s.combat,damage:clamp(Number(s.damage)||0,0,100),shot:validShot(s.shot)}},remove:id=>{let o=remote.get(id);if(o){disposeGroup(o.g);remote.delete(id)}}});
function syncPeers(dt){for(let a of mp?.peers.values()||[]){let s=a.state,o=remote.get(a.id);if(!s.active||!session||s.map!==session.map||(!started&&!finished)){if(o)o.g.visible=false;continue}if(!o||o.id!==s.car){if(o)disposeGroup(o.g);o=model(cars[s.car],{...defaults,color:cars[s.car].color},true);o.id=s.car;o.g.position.set(s.x,.10+surfaceHeight(s.x,s.z,terrainMap),s.z);remote.set(a.id,o)}o.g.visible=true;if(o.lastSeq!==a.seq){let t=Math.max(.05,(a.seen-(o.lastSeen||a.seen-200))/1000);o.vx=clamp((s.x-(o.lastX??s.x))/t,-90,90);o.vz=clamp((s.z-(o.lastZ??s.z))/t,-90,90);o.lastX=s.x;o.lastZ=s.z;o.lastSeen=a.seen;o.lastSeq=a.seq}o.g.position.x+=(s.x-o.g.position.x)*Math.min(1,dt*9);o.g.position.z+=(s.z-o.g.position.z)*Math.min(1,dt*9);o.g.position.y=.10+surfaceHeight(o.g.position.x,o.g.position.z,terrainMap);o.g.rotation.y+=angle(s.yaw,o.g.rotation.y)*Math.min(1,dt*9);damageVisual(o,s.damage);if(active&&session.online&&session.combat&&s.online&&s.combat&&s.diff===session.diff&&!s.done&&s.shot&&s.shot.target===mp.id&&s.shot.seq>(seenShots.get(a.id)||0)){seenShots.set(a.id,s.shot.seq);if(Math.hypot(p.x-s.x,p.z-s.z)<48&&Math.abs(angle(Math.atan2(p.x-s.x,p.z-s.z),s.yaw))<.5){hurt(s.shot.kind==='EMP'?5:9,'Cyber hit');if(s.shot.kind==='EMP'&&shield<=0){p.vx*=.58;p.vz*=.58}}}}}
let loading=false;function recoverError(e,stage){console.error('Drift Dynasty '+stage,e);active=false;started=false;finished=false;loading=false;keys.clear();touchKeys.clear();steer=0;acc=0;try{updateSound()}catch{}$('menu').hidden=false;$('hud').hidden=true;$('touch').hidden=true;$('result').hidden=true;$('start').disabled=false;$('start').textContent='Retry event';$('resume').hidden=true;note(stage+' failed: '+String(e?.message||e).slice(0,160)+'. Try Mobile performance in Settings. Your saved garage is intact.')}function beginEvent(){if(loading||$('start').disabled)return;loading=true;$('start').disabled=true;$('start').textContent='Loading circuit…';note('Preparing cars and track…');requestAnimationFrame(()=>{try{start();note('')}catch(e){recoverError(e,'Event start')}finally{loading=false;if(active)$('start').disabled=false}})}$('start').onclick=beginEvent;$('resume').onclick=()=>{showMenu(false);initSound()};$('pause').onclick=()=>showMenu(true);$('cam').onclick=()=>view=(view+1)%4;$('resetCar').onclick=()=>reset();$('firePickup').onclick=firePickup;$('finishPractice').onclick=()=>{if(practice&&active)finish()};$('return').onclick=()=>{$('result').hidden=true;started=false;showMenu(true)};
addEventListener('keydown',e=>{if(e.target.closest?.('input,select,textarea,.wilco-mp'))return;let k=e.key===' '?'space':e.key.toLowerCase();if(active&&['space','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='escape'&&e.repeat)return;if(k==='escape'&&started&&!finished){showMenu(active);return}if(!active)return;keys.add(k);if(e.repeat)return;if(k==='v')view=(view+1)%4;if(k==='r')reset();if(k==='f')firePickup();if(k==='x'&&practice)finish()});addEventListener('keyup',e=>keys.delete(e.key===' '?'space':e.key.toLowerCase()));addEventListener('blur',()=>{keys.clear();touchKeys.clear();steer=0});let stick=$('stick'),id=null,origin=0;stick.onpointerdown=e=>{e.preventDefault();id=e.pointerId;origin=e.clientX;try{stick.setPointerCapture(id)}catch{}};stick.onpointermove=e=>{if(id!==e.pointerId)return;steer=clamp((e.clientX-origin)/40,-1,1);$('knob').style.transform='translate(-50%,-50%) translateX('+steer*28+'px)'};stick.onpointerup=stick.onpointercancel=stick.onlostpointercapture=()=>{id=null;steer=0;$('knob').style.transform='translate(-50%,-50%)'};for(let b of document.querySelectorAll('[data-key]')){b.onpointerdown=e=>{e.preventDefault();initSound();try{b.setPointerCapture(e.pointerId)}catch{}touchKeys.add(b.dataset.key)};b.onpointerup=b.onpointercancel=b.onlostpointercapture=()=>touchKeys.delete(b.dataset.key)}
let last=performance.now(),acc=0,draw=0,nextDraw=0,hu=0;function frame(now){requestAnimationFrame(frame);let dt=clamp((now-last)/1000,0,.10);last=now;if(document.hidden)return;if(active){acc+=dt;let n=0;try{while(acc>=1/120&&n++<12&&active){step(1/120);acc-=1/120}}catch(e){recoverError(e,'Driving simulation')}}else acc=0;try{mp?.tick(now);syncPeers(dt)}catch(e){console.warn('Multiplayer update skipped',e)}if(toastTime>0&&(toastTime-=dt)<=0)$('toast').hidden=true;if(active&&now-hu>100){hu=now;try{hud()}catch(e){recoverError(e,'Race interface')}}if(!mobile||now>=nextDraw-.2){let frameDt=draw?clamp((now-draw)/1000,0,.1):1/60;draw=now;if(mobile)nextDraw=nextDraw&&now-nextDraw<100?nextDraw+1000/30:now+1000/30;try{cameraStep(frameDt,clamp(acc*120,0,1))}catch(e){if(active||loading)recoverError(e,'3D rendering');else console.warn('Preview rendering unavailable',e)}}}document.addEventListener('visibilitychange',()=>{if(document.hidden&&active)showMenu(true);if(!document.hidden){last=performance.now();draw=nextDraw=0;acc=0;if(p)previousPose=copyPose(p);resetCamera=true}});buildTrack(maps[0]);player=model(spec(),build());p=stateAt(track.p[0]);previousPose=copyPose(p);pose(player,p,0);if(new URLSearchParams(location.search).has('room'))tab='Online';renderMenu();requestAnimationFrame(frame);
